    response = await sendProviderRequest(
      sharedProviderHttpClient(),
      _request(url),
      cancelToken,
    );
  } on TimeoutException catch (e) {
    return CallOutcome('connect-watchdog', sw.elapsed, sw.elapsed, error: '$e');
